args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?husband ?husbandLabel ?deathPlace ?deathPlaceLabel WHERE {
  dbr:Princess_Caroline_Wilhelmina_Sophia_of_Hesse-Kassel dbo:spouse ?husband .
  OPTIONAL { ?husband dbo:deathPlace ?deathPlace. }
  OPTIONAL { ?husband dbp:deathPlace ?deathPlace. }
  OPTIONAL { ?husband rdfs:label ?husbandLabel. FILTER(lang(?husbandLabel) = "en") }
  OPTIONAL { ?deathPlace rdfs:label ?deathPlaceLabel. FILTER(lang(?deathPlaceLabel) = "en") }
}

